<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);$result=mysqli_query($koneksi,"SELECT f.*,u.nama_universitas,(SELECT COUNT(*) FROM program_studi ps WHERE ps.id_fakultas=f.id_fakultas) jumlah_prodi FROM fakultas f JOIN universitas u ON f.id_universitas=u.id_universitas ORDER BY f.id_fakultas DESC");?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fakultas</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading page-heading-flex"><div><span class="eyebrow">MASTER DATA</span><h1>Fakultas</h1><p>Daftar fakultas pada universitas.</p></div><a class="btn btn-primary" href="fakultas_tambah.php">+ Tambah Fakultas</a></div><?php flash_html();?><div class="dashboard-panel"><div class="table-responsive"><table class="data-table"><thead><tr><th>No</th><th>Kode</th><th>Nama Fakultas</th><th>Universitas</th><th>Jumlah Prodi</th><th>Aksi</th></tr></thead><tbody><?php $no=1;while($r=mysqli_fetch_assoc($result)):?><tr><td><?=$no++?></td><td><span class="badge"><?=e($r['kode_fakultas'])?></span></td><td><strong><?=e($r['nama_fakultas'])?></strong></td><td><?=e($r['nama_universitas'])?></td><td><?=$r['jumlah_prodi']?></td><td><div class="action-group"><a class="btn btn-sm btn-outline" href="fakultas_edit.php?id=<?=$r['id_fakultas']?>">Edit</a><form method="post" action="fakultas_hapus.php" onsubmit="return confirm('Hapus fakultas ini? Pastikan tidak memiliki prodi.');"><input type="hidden" name="id" value="<?=$r['id_fakultas']?>"><?=csrf_field()?><button class="btn btn-sm btn-danger">Hapus</button></form></div></td></tr><?php endwhile;?></tbody></table></div></div></main><script src="script.js"></script></body></html>